css:
.custom-table {
        width: 100%;
        border-collapse: collapse;
        border: 1px solid #969696 !important;
    }
.signature-table{
       width: 100%;
        border-collapse: collapse;
        border: 1px solid #969696 !important;

}



    .custom-table th,
    .custom-table td {
        border: 1px solid #969696 !important;
        padding: 4px;
    }

    .custom-table td {
        font-size: 11px;
        font-weight: 600;
    }


    .custom-table th {
        background-color: #DBDBDB !important;
        text-align: center;
        font-size: 12px;
        font-weight: 600;
        font-family: Arial, Helvetica, sans-serif;
        color: black;
        width:50%;
    }

.info-field-group {
    display: flex;
    align-items: flex-start;
    min-height: 22px;
    line-height: 1.5;
}
.passed-section {

    font-family: "Times New Roman", Times, serif;
    font-size: 12px;
}

.passed-row {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-top:5px;
}

.passed-title {
    font-weight: bold;
    font-size:12px;
}

.passed-amount {
    font-weight: bold;
    font-size:12px;
}

.amount-in-words {
    font-style: italic;
    font-size: 12px;
}
.signature-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 50px;
    font-family: "Times New Roman", Times, serif;
    font-size: 13px;
}

.signature-table td {
    width: 33.33%;
    border: none !important;
    vertical-align: bottom;
    padding: 5px 10px;
    text-align: center;
    border: 1px solid #969696 !important;
    padding: 4px;
}



.signature-space {
    height: 100px;
}

.signature-table strong {
    font-weight: bold;
}

.signature-table span {
    font-size: 11px;
}



.signature-container {
    display: flex;
    width: 100%;
    margin-top: 40px;
    align-items: flex-start;
    justify-content: space-between;

}
.signature-container1 {
    display: flex;
    width: 100%;
    margin-top: 40px;
    justify-content: center;

}

.signature-box {
    width: 33.33%;
}

.prepared {
    text-align: left;
}

.finance {
    text-align: center;
}

.approving {
    text-align: center;
}

.signature-space {
    height: 35px;
}

.signature-box span {
    font-size: 10px;
}
